        self.data = data
        self.next = None

def remove_duplicates(head):
    if head is None or head.next is None:
        return head

    current = head
    seen = set()

    while current is not None:
        if current.data in seen:
            current.next = current.next.next
        else:
            seen.add(current.data)
            current = current.next

    return head
```

